 const categories={images:{title:'Image tools.',description:'A different format. Just the right finishing touch.',input:'little-ideas.png',stem:'little-ideas',formats:[['PNG','png','Lossless image with transparency.'],['JPG','jpg','A widely compatible image format.'],['WEBP','webp','A modern image format for the web.'],['AVIF','avif','A compact, modern image format.'],['TIFF','tiff','A high-quality image container.'],['SVG','svg','Embed the image or trace approximate paths.'],['PDF','pdf','Put your image on a PDF page.']],initial:2,tools:[['CROP','crop','Crop to focus on what matters.'],['RESIZE','resize','Set an output width and keep proportions.'],['QUALITY','quality','Balance file size and output quality.'],['MIRROR','mirror','Mirror your image horizontally.'],['FLIP','flip','Flip your image vertically.'],['SVG MODE','svg','Choose lossless embedding or approximate tracing.']]},pdf:{title:'PDF tools.',description:'Convert the document. Consider every page.',input:'solar-lab.pdf',stem:'solar-lab',formats:[['AI PACK','zip','Page images, Markdown chunks and source notes.'],['PNG','png','Render the first page as a PNG.'],['JPG','jpg','Render the first page as a JPG.'],['WEBP','webp','Render the first page as a WebP.'],['TXT','txt','Extract embedded text with page references.'],['MD','md','Infer headings, ruled tables and code blocks.']],initial:0,tools:[['TEXT','text','Replace supported original text.'],['IMAGES','image','Remove or replace supported embedded images.'],['COMMENT','comment','Add a native PDF comment.'],['HIGHLIGHT','highlight','Mark the passage that matters.'],['DRAW','ink','Draw freehand ink annotations.'],['PAGES','pages','Reorder, rotate, add or remove pages.'],['FORMS','forms','Fill existing standard interactive fields.'],['SIGN','signature','Add a drawn visual signature.']]},documents:{title:'Document tools.',description:'Give your words a format that fits.',input:'field-notes.md',stem:'field-notes',formats:[['TXT','txt','Plain, portable text.'],['MD','md','Markdown for structured text.'],['HTML','html','Export a text-oriented HTML document.'],['PDF','pdf','Headings, lists, code and tables, formatted.']],initial:3,tools:[['PREVIEW','preview','Compare your original and converted document.'],['BATCH','batch','Queue compatible documents in Studio.'],['SAVE TO','folder','Choose where converted copies are saved.']]},data:{title:'Data tools.',description:'Rows, columns, and a little more flexibility.',input:'observations.csv',stem:'observations',formats:[['JSON','json','Structured data from CSV or TSV.'],['CSV','csv','Comma-separated rows and columns.'],['TSV','tsv','Tab-separated rows and columns.'],['TXT','txt','An accessible plain-text export.']],initial:0,tools:[['PREVIEW','preview','Inspect your original and converted data.'],['BATCH','batch','Convert a queue with per-file formats.'],['SAVE TO','folder','Keep outputs beside originals or in a folder.']]}};
 let category='images',formatIndex=2,toolIndex=0,sound=false,audio=null,lastTick=0;
